import 'package:flutter_test/flutter_test.dart';
import 'package:solo_android/relay/e2e.dart';

String hexToB64u(String hex) => b64u([for (var i = 0; i < hex.length; i += 2) int.parse(hex.substring(i, i + 2), radix: 16)]);
String toHex(List<int> b) => b.map((x) => x.toRadixString(16).padLeft(2, '0')).join();
List<int> fromHex(String h) => [for (var i = 0; i < h.length; i += 2) int.parse(h.substring(i, i + 2), radix: 16)];

// Vectors generated by packages/crypto/src/e2e.test.ts. They must match exactly: this is the proof that the phone and
// the desktop speak the same cryptography.
void main() {
  test('ed25519 identity and signature match the TypeScript implementation', () async {
    final id = await identityFromSeed(hexToB64u('000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f'));
    expect(id.pub, 'A6EHv_POEL4dcN0Y50vAmWfk1jCbpQ1fHdyGZBJVMbg');
    expect(id.id, '56475aa75463474c0285df5dbf2bcab73da651358839e9b77481b2eab107708c');
    expect(await signText(id, 'solo-vector'), 'cPvddUAeisrYjFElnhL7TTQOuZpjQ0rWL_29h2Q5Ec3zB62_x-kvWu2CWWtkp60V_cPPSSWnl9zQHDUuj2PDCA');
    expect(await verifyText(id.pub, 'solo-vector', await signText(id, 'solo-vector')), true);
    expect(await verifyText(id.pub, 'tampered', await signText(id, 'solo-vector')), false);
  });

  test('x25519, hkdf and aes-256-gcm match the TypeScript implementation', () async {
    final a = await ephFromPriv(hexToB64u('a' * 64)), b = await ephFromPriv(hexToB64u('b' * 64));
    expect(a.pub, 'FMqeTTh7zPNXRuBAfaqsxrKKT4RF71pRWIlNuYPiQHA');
    expect(b.pub, 'awthbXGOU2kSNtO-PObUT50og2Qm2BMF0TH0iCBvjSs');
    final shared = await dh(a, b.pub);
    expect(toHex(shared), '2f6d4d0247b4216d9114a87cf9206bc9c65c1b62593f18b7f3474a747e615229');
    expect(toHex(await dh(b, a.pub)), toHex(shared));
    final km = await hkdf64(shared, fromHex('00112233445566778899aabbccddeeff'), 'solo-session-v1|I|R');
    expect(toHex(km), '08b54acd555dc46fbcbaf6650ae299a015c8112f5ed21574935f754bb606f532431dc8dfceaaf9c0e30cb40b286b41b3896de663408e433a986489714227cc4c');
    final key = km.sublist(0, 32);
    final ct = await aeadSeal(key, 7, 'solo-data|I|R', 'hello solo');
    expect(ct, 'j28t9n1HUySAWD_W5_mgDILMTOeojQjAubU');
    expect(await aeadOpen(key, 7, 'solo-data|I|R', ct), 'hello solo');
    expect(await aeadOpen(key, 8, 'solo-data|I|R', ct), isNull);
  });

  test('pairing code helpers match the TypeScript implementation', () {
    expect(rendezvousKey('K7QM-2X9D-4TRW'), '97ade3067fe60949fd81501420bee7cc');
    expect(rendezvousKey('k7qm2x9d4trw'), rendezvousKey('K7QM-2X9D-4TRW'));
    expect(pairingProof('K7QM-2X9D-4TRW', 'req', 'host', 'joiner', 'nonce', 'jp', 'hp'),
        '163984a886401752faee7289d177a4c07ab83cd62ecd18fb02ebb2f5a856fe30');
    expect(normalizeCode('abcd-ef12-oil3'), 'ABCDEF120113');
  });

  test('handshake and session work in Dart, with replay and tamper protection', () async {
    final A = await generateIdentity(), B = await generateIdentity();
    final i = await hsInitiate(A, B.id);
    final r = (await hsRespond(B, A.id, A.pub, i.msg))!;
    final sa = (await hsFinish(A, B.id, B.pub, i.state, r.msg))!;
    final sb = r.session;
    final f1 = await sa.seal('one'), f2 = await sa.seal('two');
    expect(await sb.open(f2.c, f2.ct), 'two');
    expect(await sb.open(f1.c, f1.ct), isNull); // older counter
    expect(await sb.open(f2.c, f2.ct), isNull); // replay
    final back = await sb.seal('pong');
    expect(await sa.open(back.c, back.ct), 'pong');
    final own = await sa.seal('mine');
    expect(await sa.open(own.c, own.ct), isNull); // reflection
    final C = await generateIdentity();
    expect(await hsRespond(B, A.id, C.pub, i.msg), isNull); // wrong trusted key
    expect(await hsFinish(A, B.id, C.pub, i.state, r.msg), isNull); // impersonated responder
  });
}
